## 🛠️ Sample “Hello, World” – Full Round‑Trip

```csharp
using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

public class BlogPost
{
    [JsonPropertyName("id")]          // JSON: id
    public int Id { get; set; }

    [JsonPropertyName("title")]       // JSON: title
    public string Title { get; set; }

    [JsonPropertyName("content")]     // JSON: content
    public string Content { get; set; }

    // Read‑only property – we want it serialized
    [JsonInclude]
    public DateTime PublishedUtc { get; }

    // Ignored by default, but we want to capture unknown fields
    [JsonExtensionData]
    public IDictionary<string, JsonElement> Extras { get; set; } =
        new Dictionary<string, JsonElement>();

    public BlogPost(string title, string content, DateTime publishedUtc)
    {
        Title = title;
        Content = content;
        PublishedUtc = publishedUtc;
    }
}

class Program
{
    static void Main()
    {
        var post = new BlogPost("Hello", "World", DateTime.UtcNow);

        // Options – everything we need
        var opts = new JsonSerializerOptions
        {
            WriteIndented = true,
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
            PropertyNameCaseInsensitive = true,
            Converters = { new JsonStringEnumConverter() }
        };

        // Serialize
        string json = JsonSerializer.Serialize(post, opts);
        Console.WriteLine("Serialized JSON:");
        Console.WriteLine(json);

        // Deserialize
        var deserialized = JsonSerializer.Deserialize<BlogPost>(json, opts);
        Console.WriteLine("\nDeserialized object:");
        Console.WriteLine($"Id: {deserialized.Id}, Title: {deserialized.Title}");
    }
}
```

**Key take‑aways:**

- `PropertyNamingPolicy.CamelCase` + `[JsonPropertyName]` → JSON property names in camelCase.  
- `JsonInclude` on a read‑only property so it appears in JSON.  
- `JsonExtensionData` captures any extra JSON that isn’t mapped to a known property.  
- `JsonStringEnumConverter` is wired in the options (shown for completeness).  

